const incoming =
  $input.first()?.json ?? {};

const body =
  incoming.body ?? {};

const clean = value =>
  String(value ?? '').trim();

const action =
  clean(body.action).toLowerCase();

const opportunityKey =
  clean(body.opportunity_key);

const emailSubject =
  clean(body.email_subject);

const emailDraft =
  clean(body.email_draft);

const linkedinConnectionNote =
  clean(body.linkedin_connection_note);

const linkedinMessage =
  clean(body.linkedin_message);

const allowedActions = [
  'save_draft',
  'approve_and_send',
];

const errors = [];

if (!allowedActions.includes(action)) {
  errors.push(
    'action must be save_draft or approve_and_send.'
  );
}

if (!opportunityKey) {
  errors.push(
    'opportunity_key is required.'
  );
}

if (!emailSubject) {
  errors.push(
    'email_subject is required.'
  );
}

if (!emailDraft) {
  errors.push(
    'email_draft is required.'
  );
}

return [
  {
    json: {
      request_valid:
        errors.length === 0,

      http_status:
        errors.length === 0
          ? 200
          : 400,

      errors,

      action,
      opportunity_key:
        opportunityKey,

      email_subject:
        emailSubject,

      email_draft:
        emailDraft,

      linkedin_connection_note:
        linkedinConnectionNote,

      linkedin_message:
        linkedinMessage,
    },
  },
];

const request =
  $('Validate Outreach Request')
    .first()
    .json ?? {};

const clean = value =>
  String(value ?? '').trim();

const upper = value =>
  clean(value).toUpperCase();

const rows = $input
  .all()
  .map(item => item.json ?? {})
  .filter(
    row =>
      clean(row.opportunity_key)
  );

const requestedKey =
  clean(request.opportunity_key);

const row =
  rows.find(
    candidate =>
      clean(candidate.opportunity_key) ===
      requestedKey
  ) ?? null;


function blocked(
  message,
  httpStatus = 409,
  reasons = [],
  extra = {},
) {
  return [
    {
      json: {
        can_update: false,
        success: false,
        http_status: httpStatus,
        message,
        action:
          request.action,
        opportunity_key:
          requestedKey,
        blocking_reasons:
          reasons,
        ...extra,
      },
    },
  ];
}


function normalizeDomain(value) {
  let domain =
    clean(value).toLowerCase();

  if (!domain) {
    return '';
  }

  domain = domain
    .replace(/^https?:\/\//, '')
    .split('/')[0]
    .split('?')[0]
    .split('#')[0]
    .replace(/^www\./, '')
    .replace(/\.$/, '');

  return domain;
}


function normalizeEmail(value) {
  return clean(value).toLowerCase();
}


function normalizeLinkedIn(value) {
  return clean(value)
    .toLowerCase()
    .split('?')[0]
    .split('#')[0]
    .replace(/\/+$/, '');
}


function normalizeCompanyName(value) {
  return clean(value)
    .toLowerCase()
    .replace(/\s+/g, ' ');
}


function sharesCampaignIdentity(
  first,
  second,
) {
  const firstDomain =
    normalizeDomain(
      first.company_domain
    );

  const secondDomain =
    normalizeDomain(
      second.company_domain
    );

  if (
    firstDomain &&
    secondDomain &&
    firstDomain === secondDomain
  ) {
    return true;
  }


  const firstEmail =
    normalizeEmail(
      first.contact_email
    );

  const secondEmail =
    normalizeEmail(
      second.contact_email
    );

  if (
    firstEmail &&
    secondEmail &&
    firstEmail === secondEmail
  ) {
    return true;
  }


  const firstLinkedIn =
    normalizeLinkedIn(
      first.contact_linkedin_url
    );

  const secondLinkedIn =
    normalizeLinkedIn(
      second.contact_linkedin_url
    );

  if (
    firstLinkedIn &&
    secondLinkedIn &&
    firstLinkedIn === secondLinkedIn
  ) {
    return true;
  }


  /*
   * Company name is only a fallback when
   * neither row has a usable company domain.
   */
  if (
    !firstDomain &&
    !secondDomain
  ) {
    const firstCompany =
      normalizeCompanyName(
        first.company_name
      );

    const secondCompany =
      normalizeCompanyName(
        second.company_name
      );

    if (
      firstCompany &&
      secondCompany &&
      firstCompany === secondCompany
    ) {
      return true;
    }
  }

  return false;
}


function campaignRank(candidate) {
  const candidateOutreachStatus =
    upper(candidate.outreach_status);

  const candidateResearchStatus =
    upper(
      candidate.contact_research_status
    );

  const candidateApproval =
    upper(
      candidate.outreach_approval
    );

  const candidateSentAt =
    clean(candidate.sent_at);


  if (
    candidateSentAt ||
    [
      'SENT',
      'REPLIED',
      'FOLLOW_UP_DUE',
    ].includes(
      candidateOutreachStatus
    )
  ) {
    return 500;
  }


  if (
    candidateApproval === 'APPROVED' ||
    candidateOutreachStatus ===
      'APPROVED'
  ) {
    return 400;
  }


  if (
    candidateOutreachStatus ===
    'DRAFT_READY'
  ) {
    return 300;
  }


  if (
    candidateResearchStatus ===
    'COMPLETED'
  ) {
    return 200;
  }


  if (
    candidateResearchStatus ===
    'IN_PROGRESS'
  ) {
    return 100;
  }


  return 0;
}


if (!row) {
  return blocked(
    'The requested opportunity was not found.',
    404,
    [
      'No matching Application_Tracker row exists.',
    ],
  );
}


const applicationStatus =
  upper(row.application_status);

const outreachMode =
  upper(row.outreach_mode);

const outreachStatus =
  upper(row.outreach_status);

const contactResearchStatus =
  upper(row.contact_research_status);

const emailConfidence =
  upper(
    row.contact_email_confidence
  );

const contactEmail =
  clean(row.contact_email);

const sentAt =
  clean(row.sent_at);


if (
  requestedKey.startsWith('test::')
) {
  return blocked(
    'Test opportunities cannot be controlled through the production outreach API.',
  );
}


const eligibleForOutreach =
  applicationStatus === 'APPLIED' ||
  outreachMode === 'ADJACENT_ROLE' ||
  outreachMode === 'SPECULATIVE';


if (!eligibleForOutreach) {
  return blocked(
    'Outreach requires either an APPLIED opportunity or an explicitly selected adjacent or speculative outreach strategy.',
    409,
    [
      `Application status: ${
        applicationStatus || 'EMPTY'
      }.`,
      `Outreach mode: ${
        outreachMode || 'EMPTY'
      }.`,
    ],
  );
}


if (
  sentAt ||
  outreachStatus === 'SENT'
) {
  return blocked(
    'Outreach was already sent for this opportunity.',
    409,
  );
}


/*
 * Company-level campaign protection.
 *
 * Find rows sharing the same company domain,
 * contact email, LinkedIn profile, or fallback
 * company name.
 */
const relatedCampaignRows =
  rows.filter(
    candidate =>
      sharesCampaignIdentity(
        row,
        candidate,
      )
  );

const activeCampaignRows =
  relatedCampaignRows
    .filter(
      candidate =>
        campaignRank(candidate) > 0
    )
    .sort(
      (first, second) => {
        const rankDifference =
          campaignRank(second) -
          campaignRank(first);

        if (rankDifference) {
          return rankDifference;
        }

        const sentDifference =
          clean(second.sent_at)
            .localeCompare(
              clean(first.sent_at)
            );

        if (sentDifference) {
          return sentDifference;
        }

        return clean(
          first.opportunity_key
        ).localeCompare(
          clean(
            second.opportunity_key
          )
        );
      }
    );


const canonicalCampaign =
  activeCampaignRows[0] ?? null;

const canonicalKey =
  clean(
    canonicalCampaign
      ?.opportunity_key
  );


if (
  canonicalCampaign &&
  canonicalKey &&
  canonicalKey !== requestedKey
) {
  const canonicalCompany =
    clean(
      canonicalCampaign.company_name
    ) ||
    clean(row.company_name) ||
    'This company';

  const canonicalPosition =
    clean(
      canonicalCampaign.position_title
    ) ||
    'another opportunity';

  const canonicalContact =
    clean(
      canonicalCampaign.contact_name
    ) ||
    clean(
      canonicalCampaign.contact_email
    ) ||
    'the saved company contact';

  const canonicalStatus =
    upper(
      canonicalCampaign.outreach_status
    ) ||
    upper(
      canonicalCampaign
        .contact_research_status
    ) ||
    'ACTIVE';

  return blocked(
    `${canonicalCompany} already has an active company outreach campaign.`,
    409,
    [
      `Canonical campaign: ${canonicalPosition}.`,
      `Contact: ${canonicalContact}.`,
      `Campaign status: ${canonicalStatus}.`,
      'A second email or LinkedIn outreach is not allowed for this company/contact.',
    ],
    {
      duplicate_campaign: true,

      covered_by_opportunity_key:
        canonicalKey,

      covered_by_company_name:
        canonicalCompany,

      covered_by_position_title:
        canonicalPosition,

      covered_by_contact:
        canonicalContact,

      covered_by_status:
        canonicalStatus,
    },
  );
}


if (
  request.action ===
  'approve_and_send'
) {
  const approvalProblems = [];

  if (
    contactResearchStatus !==
    'COMPLETED'
  ) {
    approvalProblems.push(
      'Contact research is not completed.'
    );
  }

  if (!contactEmail) {
    approvalProblems.push(
      'No contact email is available.'
    );
  }

  if (
    !['HIGH', 'MEDIUM','USER_VERIFIED',].includes(
      emailConfidence
    )
  ) {
    approvalProblems.push(
      'Contact email confidence must be HIGH or MEDIUM or USER_VERIFIED.'
    );
  }

  if (
    !clean(row.resume_file_id)
  ) {
    approvalProblems.push(
      'Resume file ID is missing.'
    );
  }

  if (
    !clean(row.resume_filename)
  ) {
    approvalProblems.push(
      'Resume filename is missing.'
    );
  }

  if (approvalProblems.length) {
    return blocked(
      'The email is not ready for approval and sending.',
      409,
      approvalProblems,
    );
  }
}


const now =
  new Date().toISOString();

const shouldSend =
  request.action ===
  'approve_and_send';


return [
  {
    json: {
      ...row,

      can_update: true,
      success: true,
      http_status: 200,

      action:
        request.action,

      opportunity_key:
        requestedKey,

      application_status:
        applicationStatus,

      outreach_mode:
        outreachMode,

      email_subject:
        clean(
          request.email_subject
        ),

      email_draft:
        clean(
          request.email_draft
        ),

      linkedin_connection_note:
        clean(
          request.linkedin_connection_note
        ),

      linkedin_message:
        clean(
          request.linkedin_message
        ),

      draft_final_status:
        'READY',

      draft_generated_at:
        clean(
          row.draft_generated_at
        ) || now,

      outreach_status:
        'DRAFT_READY',

      outreach_approval:
        shouldSend
          ? 'APPROVED'
          : 'PENDING',

      should_send:
        shouldSend,

      duplicate_campaign:
        false,

      last_updated:
        now,
    },
  },
];

const context =
  $('Prepare Outreach Update')
    .first()
    .json ?? {};

return [
  {
    json: context,
  },
];

const update =
  $('Prepare Outreach Update')
    .first()
    .json ?? {};

return [
  {
    json: {
      success: true,
      http_status: 200,

      action:
        update.action,

      message:
        'Outreach drafts saved successfully.',

      opportunity_key:
        update.opportunity_key,

      outreach_status:
        update.outreach_status,

      outreach_approval:
        update.outreach_approval,

      draft_final_status:
        update.draft_final_status,

      last_updated:
        update.last_updated,
    },
  },
];

const result =
  $input.first()?.json ?? {};

const success =
  result.success === true &&
  result.send_status === 'SENT';

return [
  {
    json: {
      ...result,

      success,

      http_status:
        success
          ? 200
          : 409,

      message:
        result.message ||
        (
          success
            ? 'Approved outreach email sent successfully.'
            : 'The sender did not send the email.'
        ),
    },
  },
];
